     9	import br.com.marealta.domain.Room;
    10	import br.com.marealta.mail.ConfirmationEmail;
    11	import br.com.marealta.mail.Mailer;
    12	import br.com.marealta.persistence.Db;
    13	import br.com.marealta.persistence.ReservationRepository;
    14	import br.com.marealta.persistence.RoomRepository;
    15	
    16	import java.sql.Connection;
    17	import java.sql.SQLException;
    18	
    19	public final class ReservationService {
    20	    private final Db db;
    21	    private final RoomRepository rooms;
    22	    private final ReservationRepository reservations;
    23	    private final Mailer mailer;
    24	
    25	    public ReservationService(Db db, RoomRepository rooms, ReservationRepository reservations, Mailer mailer) {
    26	        this.db = db;
    27	        this.rooms = rooms;
    28	        this.reservations = reservations;
    29	        this.mailer = mailer;
    30	    }
    31	
    32	    public Reservation create(NewReservation request) {
    33	        return db.transaction(connection -> {
    34	            Room room = rooms.findForUpdate(connection, request.roomNumber())
    35	                    .orElseThrow(() -> new DomainException(ErrorCode.ROOM_NOT_FOUND, "Quarto não encontrado"));
    36	            if (request.guests() > room.capacity()) {
    37	                throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    38	                        "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    39	            }
    40	            if (reservations.existsOverlapping(connection, room.number(), request.checkIn(), request.checkOut())) {
    41	                throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    42	                        "O quarto " + room.number() + " já está reservado em alguma das noites");
    43	            }
    44	            Reservation reservation = Reservation.pending(room, request.guest(), request.checkIn(),
    45	                    request.checkOut(), request.guests(), request.ratePlan());
    46	            long id = reservations.insert(connection, reservation);
    47	            return reservations.find(connection, id).orElseThrow();
    48	        });
    49	    }
    50	
    51	    public Reservation get(long id) {
    52	        return db.transaction(connection -> load(connection, id, false));
    53	    }
    54	
    55	    public Reservation confirm(long id) {
    56	        return db.transaction(connection -> {
    57	            Reservation reservation = load(connection, id, true);
    58	            reservation.confirm();
    59	            reservations.updateState(connection, reservation);
    60	            Receipt receipt = receiptOf(connection, reservation);
    61	            mailer.send(connection, ConfirmationEmail.to(reservation.guest().email(),
    62	                    reservation.guest().name(), receipt));
    63	            return reservation;
    64	        });
    65	    }
    66	
    67	    public Reservation cancel(long id) {
    68	        return change(id, Reservation::cancel);
    69	    }
    70	
    71	    public Reservation checkIn(long id) {
    72	        return change(id, Reservation::checkIn);
    73	    }
    74	
    75	    public Receipt checkOut(long id) {
    76	        return db.transaction(connection -> {
    77	            Reservation reservation = load(connection, id, true);
    78	            reservation.checkOut();
    79	            reservations.updateState(connection, reservation);
    80	            return receiptOf(connection, reservation);
    81	        });
    82	    }
    83	
    84	    /** A segunda via do comprovante, que só existe para reserva paga. */
    85	    public Receipt document(long id) {
    86	        return db.transaction(connection -> {
    87	            Reservation reservation = load(connection, id, false);
    88	            ReservationStatus status = reservation.status();
    89	            if (!status.isPaid()) {
    90	                throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
    91	                        "Só há comprovante para reserva paga");
    92	            }
    93	            return receiptOf(connection, reservation);
    94	        });
    95	    }
    96	
    97	    private Reservation change(long id, java.util.function.Consumer<Reservation> operation) {
    98	        return db.transaction(connection -> {
    99	            Reservation reservation = load(connection, id, true);
   100	            operation.accept(reservation);
   101	            reservations.updateState(connection, reservation);
   102	            return reservation;
   103	        });
   104	    }
   105	
   106	    private Reservation load(Connection connection, long id, boolean forUpdate) throws SQLException {
   107	        return (forUpdate ? reservations.findForUpdate(connection, id) : reservations.find(connection, id))
   108	                .orElseThrow(() -> new DomainException(ErrorCode.RESERVATION_NOT_FOUND,
   109	                        "Reserva não encontrada"));
   110	    }
   111	
   112	    private Receipt receiptOf(Connection connection, Reservation reservation) throws SQLException {
   113	        Room room = rooms.find(connection, reservation.roomNumber()).orElseThrow();
   114	        return Receipt.of(reservation, room);
   115	    }
   116	}
