     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.domain.ErrorCode;
     5	import br.com.marealta.domain.Guest;
     6	import br.com.marealta.domain.NewReservation;
     7	import br.com.marealta.domain.RatePlan;
     8	import com.fasterxml.jackson.databind.JsonNode;
     9	import com.fasterxml.jackson.databind.ObjectMapper;
    10	
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.time.format.DateTimeParseException;
    14	
    15	/** Lê e valida o que chega do site; qualquer problema vira INVALID_REQUEST. */
    16	final class RequestParser {
    17	    private final ObjectMapper mapper;
    18	
    19	    RequestParser(ObjectMapper mapper) {
    20	        this.mapper = mapper;
    21	    }
    22	
    23	    NewReservation reservation(String body) {
    24	        JsonNode json;
    25	        try {
    26	            json = mapper.readTree(body);
    27	        } catch (Exception e) {
    28	            throw invalid("O corpo não é um JSON válido");
    29	        }
    30	        if (json == null || !json.isObject()) {
    31	            throw invalid("O corpo deve ser um objeto JSON");
    32	        }
    33	        LocalDate checkIn = date(json, "checkIn");
    34	        LocalDate checkOut = date(json, "checkOut");
    35	        if (!checkOut.isAfter(checkIn)) {
    36	            throw invalid("A saída deve ser depois da entrada");
    37	        }
    38	        int guests = integer(json, "guests");
    39	        if (guests < 1) {
    40	            throw invalid("É preciso pelo menos um hóspede");
    41	        }
    42	        return new NewReservation(integer(json, "roomNumber"),
    43	                new Guest(text(json, "guestName"), text(json, "guestEmail"), text(json, "guestCpf")),
    44	                checkIn, checkOut, guests, ratePlan(json));
    45	    }
    46	
    47	    LocalDate day(String value) {
    48	        try {
    49	            return LocalDate.parse(value);
    50	        } catch (DateTimeParseException | NullPointerException e) {
    51	            throw invalid("Data inválida, use o formato 2027-07-10");
    52	        }
    53	    }
    54	
    55	    YearMonth month(String value) {
    56	        try {
    57	            return YearMonth.parse(value);
    58	        } catch (DateTimeParseException | NullPointerException e) {
    59	            throw invalid("Mês inválido, use o formato 2027-07");
    60	        }
    61	    }
    62	
    63	    private String text(JsonNode json, String field) {
    64	        JsonNode node = json.get(field);
    65	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    66	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    67	        }
    68	        return node.asText();
    69	    }
    70	
    71	    private int integer(JsonNode json, String field) {
    72	        JsonNode node = json.get(field);
    73	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    74	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    75	        }
    76	        return node.asInt();
    77	    }
    78	
    79	    private LocalDate date(JsonNode json, String field) {
    80	        return day(text(json, field));
    81	    }
    82	
    83	    private RatePlan ratePlan(JsonNode json) {
    84	        try {
    85	            return RatePlan.valueOf(text(json, "ratePlan"));
    86	        } catch (IllegalArgumentException e) {
    87	            throw invalid("Plano de tarifa inválido");
    88	        }
    89	    }
    90	
    91	    private DomainException invalid(String message) {
    92	        return new DomainException(ErrorCode.INVALID_REQUEST, message);
    93	    }
    94	}
