    12	import com.fasterxml.jackson.databind.ObjectMapper;
    13	import com.fasterxml.jackson.databind.SerializationFeature;
    14	import com.fasterxml.jackson.databind.json.JsonMapper;
    15	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    16	import io.javalin.Javalin;
    17	import io.javalin.http.Context;
    18	
    19	import java.util.List;
    20	import java.util.Map;
    21	
    22	public final class Routes {
    23	    private static final String CSV = "text/csv; charset=utf-8";
    24	
    25	    private final ObjectMapper mapper = JsonMapper.builder()
    26	            .addModule(new JavaTimeModule())
    27	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    28	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN)
    29	            .build();
    30	    private final RequestParser parser = new RequestParser(mapper);
    31	
    32	    private final Db db;
    33	    private final RoomRepository rooms;
    34	    private final MessageRepository messages;
    35	    private final ReservationService reservations;
    36	    private final OccupancyReport occupancy;
    37	    private final RevenueReport revenue;
    38	
    39	    public Routes(Db db, RoomRepository rooms, MessageRepository messages, ReservationService reservations,
    40	                  OccupancyReport occupancy, RevenueReport revenue) {
    41	        this.db = db;
    42	        this.rooms = rooms;
    43	        this.messages = messages;
    44	        this.reservations = reservations;
    45	        this.occupancy = occupancy;
    46	        this.revenue = revenue;
    47	    }
    48	
    49	    public void register(Javalin app) {
    50	        app.get("/rooms", ctx -> json(ctx, 200, db.transaction(rooms::findAll)));
    51	        app.post("/reservations", ctx -> json(ctx, 201,
    52	                ReservationResponse.of(reservations.create(parser.reservation(ctx.body())))));
    53	        app.get("/reservations/{id}", ctx -> reservation(ctx, reservations.get(id(ctx))));
    54	        app.post("/reservations/{id}/confirmation", ctx -> reservation(ctx, reservations.confirm(id(ctx))));
    55	        app.post("/reservations/{id}/cancellation", ctx -> reservation(ctx, reservations.cancel(id(ctx))));
    56	        app.post("/reservations/{id}/check-in", ctx -> reservation(ctx, reservations.checkIn(id(ctx))));
    57	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, reservations.checkOut(id(ctx))));
    58	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, reservations.document(id(ctx))));
    59	        app.get("/messages", ctx -> {
    60	            List<Message> sent = db.transaction(messages::findAll);
    61	            json(ctx, 200, sent);
    62	        });
    63	        app.get("/reports/occupancy", ctx ->
    64	                csv(ctx, occupancy.generate(parser.day(ctx.queryParam("date")))));
    65	        app.get("/reports/revenue", ctx ->
    66	                csv(ctx, revenue.generate(parser.month(ctx.queryParam("month")))));
    67	
    68	        app.exception(DomainException.class, (e, ctx) -> json(ctx, e.code().httpStatus(), error(e.code().name(), e)));
    69	        app.exception(Exception.class, (e, ctx) -> {
    70	            e.printStackTrace();
    71	            json(ctx, 500, Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    72	        });
    73	    }
    74	
    75	    private long id(Context ctx) {
    76	        try {
    77	            return Long.parseLong(ctx.pathParam("id"));
    78	        } catch (NumberFormatException e) {
    79	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não encontrada");
    80	        }
    81	    }
    82	
    83	    private void reservation(Context ctx, br.com.marealta.domain.Reservation reservation) {
    84	        json(ctx, 200, ReservationResponse.of(reservation));
    85	    }
    86	
    87	    private Map<String, String> error(String code, Exception e) {
    88	        return Map.of("error", code, "message", String.valueOf(e.getMessage()));
    89	    }
    90	
    91	    private void csv(Context ctx, String content) {
    92	        ctx.status(200).contentType(CSV).result(content);
    93	    }
    94	
    95	    private void json(Context ctx, int status, Object body) {
    96	        try {
    97	            ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
    98	        } catch (Exception e) {
    99	            throw new IllegalStateException(e);
   100	        }
   101	    }
   102	}

