     1	package br.com.marealta.mail;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/** Passa cada mensagem, na ordem, por todas as regras que valem no modo atual. */
     7	public final class MailPipeline {
     8	    private final List<MailRule> rules;
     9	
    10	    public MailPipeline(boolean testMode, List<ScopedRule> configured) {
    11	        this.rules = configured.stream()
    12	                .filter(scoped -> scoped.scope().appliesTo(testMode))
    13	                .map(ScopedRule::rule)
    14	                .toList();
    15	    }
    16	
    17	    public List<Message> process(Message message) {
    18	        List<Message> current = List.of(message);
    19	        for (MailRule rule : rules) {
    20	            List<Message> next = new ArrayList<>();
    21	            for (Message m : current) {
    22	                if (m.isSent()) {
    23	                    next.addAll(rule.apply(m));
    24	                } else {
    25	                    next.add(m);
    26	                }
    27	            }
    28	            current = next;
    29	        }
    30	        return current;
    31	    }
    32	}
