     7	public final class Db {
     8	    @FunctionalInterface
     9	    public interface Work<T> {
    10	        T run(Connection connection) throws SQLException;
    11	    }
    12	
    13	    private final String url;
    14	    private final String user;
    15	    private final String password;
    16	
    17	    public Db(String url, String user, String password) {
    18	        this.url = url;
    19	        this.user = user;
    20	        this.password = password;
    21	    }
    22	
    23	    public <T> T transaction(Work<T> work) {
    24	        try (Connection connection = DriverManager.getConnection(url, user, password)) {
    25	            connection.setAutoCommit(false);
    26	            try {
    27	                T result = work.run(connection);
    28	                connection.commit();
    29	                return result;
    30	            } catch (SQLException | RuntimeException e) {
    31	                connection.rollback();
    32	                throw e;
    33	            }
    34	        } catch (SQLException e) {
    35	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
    36	        }
    37	    }
    38	}
