    21	    /** Diz se uma reserva na situação {@code current} pode passar para esta situação. */
    22	    public boolean canFollow(ReservationStatus current) {
    23	        return switch (this) {
    24	            case PENDING -> false;
    25	            case CONFIRMED -> current == PENDING;
    26	            case CHECKED_IN -> current == CONFIRMED;
    27	            case CHECKED_OUT -> current == CHECKED_IN;
    28	            case CANCELLED -> current == PENDING || current == CONFIRMED;
    29	        };
    30	    }
