    21	public final class ReservationRepository {
    22	    private static final String SELECT = """
    23	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan,
    24	                   nights, subtotal, discount, total, status, amount_paid, refund
    25	            FROM reservations""";
    26	
    27	    /** Grava a reserva nova e devolve o id gerado. */
    28	    public long insert(Connection connection, Reservation r) throws SQLException {
    29	        try (PreparedStatement statement = connection.prepareStatement("""
    30	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    31	                    guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    32	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""", Statement.RETURN_GENERATED_KEYS)) {
    33	            statement.setInt(1, r.roomNumber());
    34	            statement.setString(2, r.guest().name());
    35	            statement.setString(3, r.guest().email());
    36	            statement.setString(4, r.guest().cpf());
    37	            statement.setDate(5, Date.valueOf(r.arrival()));
    38	            statement.setDate(6, Date.valueOf(r.departure()));
    39	            statement.setInt(7, r.guests());
    40	            statement.setString(8, r.ratePlan().name());
    41	            statement.setInt(9, r.quote().nights());
    42	            statement.setBigDecimal(10, r.quote().subtotal());
    43	            statement.setBigDecimal(11, r.quote().discount());
    44	            statement.setBigDecimal(12, r.quote().total());
    45	            statement.setString(13, r.status().name());
    46	            statement.setBigDecimal(14, r.amountPaid());
    47	            statement.setBigDecimal(15, r.refund());
    48	            statement.executeUpdate();
    49	            try (ResultSet keys = statement.getGeneratedKeys()) {
    50	                keys.next();
    51	                return keys.getLong(1);
    52	            }
    53	        }
    54	    }
