    75	    private Optional<Reservation> findOne(Connection connection, long id, String suffix) throws SQLException {
    76	        try (PreparedStatement statement = connection.prepareStatement(SELECT + " WHERE id = ?" + suffix)) {
    77	            statement.setLong(1, id);
    78	            try (ResultSet rows = statement.executeQuery()) {
