   101	    public List<Reservation> findPaidOccupying(Connection connection, LocalDate night) throws SQLException {
   102	        String[] paid = Arrays.stream(ReservationStatus.values()).filter(ReservationStatus::isPaid)
   103	                .map(Enum::name).toArray(String[]::new);
   104	        try (PreparedStatement statement = connection.prepareStatement(
   105	                SELECT + " WHERE status = ANY (?) AND check_in <= ? AND check_out > ? ORDER BY room_number, id")) {
   106	            statement.setArray(1, connection.createArrayOf("varchar", paid));
   107	            statement.setDate(2, Date.valueOf(night));
   108	            statement.setDate(3, Date.valueOf(night));
   109	            return readAll(statement);
   110	        }
   111	    }
   112	
   113	    /** Reservas com entrada em [from, to), em ordem de entrada e de número. */
   114	    public List<Reservation> findStartingBetween(Connection connection, LocalDate from, LocalDate to)
   115	            throws SQLException {
   116	        try (PreparedStatement statement = connection.prepareStatement(
   117	                SELECT + " WHERE check_in >= ? AND check_in < ? ORDER BY check_in, id")) {
   118	            statement.setDate(1, Date.valueOf(from));
   119	            statement.setDate(2, Date.valueOf(to));
