   124	    private List<Reservation> readAll(PreparedStatement statement) throws SQLException {
   125	        try (ResultSet rows = statement.executeQuery()) {
   126	            List<Reservation> found = new ArrayList<>();
   127	            while (rows.next()) {
   128	                found.add(read(rows));
   129	            }
   130	            return found;
   131	        }
