    15	
    16	    public List<Room> findAll(Connection connection) throws SQLException {
    17	        try (PreparedStatement statement = connection.prepareStatement(
    18	                "SELECT " + COLUMNS + " FROM rooms ORDER BY number");
    19	             ResultSet rows = statement.executeQuery()) {
    20	            List<Room> rooms = new ArrayList<>();
    21	            while (rows.next()) {
    22	                rooms.add(read(rows));
    23	            }
    24	            return rooms;
    25	        }
    26	    }
    27	
    28	    /** Busca o quarto travando a linha, para que reservas simultâneas do mesmo quarto sejam atendidas em fila. */
    29	    public Optional<Room> findForUpdate(Connection connection, int number) throws SQLException {
    30	        return find(connection, number, " FOR UPDATE");
    31	    }
    32	
    33	    public Optional<Room> find(Connection connection, int number) throws SQLException {
    34	        return find(connection, number, "");
    35	    }
    36	
    37	    private Optional<Room> find(Connection connection, int number, String suffix) throws SQLException {
    38	        try (PreparedStatement statement = connection.prepareStatement(
    39	                "SELECT " + COLUMNS + " FROM rooms WHERE number = ?" + suffix)) {
    40	            statement.setInt(1, number);
    41	            try (ResultSet rows = statement.executeQuery()) {
