     6	
     7	/** Cria o que o sistema precisa no banco, se ainda não existir. */
     8	public final class Schema {
     9	    private static final List<String> STATEMENTS = List.of(
    10	            """
    11	            CREATE TABLE IF NOT EXISTS rooms (
    12	                number INTEGER PRIMARY KEY,
    13	                type VARCHAR(20) NOT NULL,
    14	                capacity INTEGER NOT NULL,
    15	                nightly_rate NUMERIC(12,2) NOT NULL
    16	            )""",
    17	            """
    18	            CREATE TABLE IF NOT EXISTS reservations (
    19	                id BIGSERIAL PRIMARY KEY,
    20	                room_number INTEGER NOT NULL REFERENCES rooms(number),
    21	                guest_name TEXT NOT NULL,
    22	                guest_email TEXT NOT NULL,
    23	                guest_cpf TEXT NOT NULL,
    24	                check_in DATE NOT NULL,
    25	                check_out DATE NOT NULL,
    26	                guests INTEGER NOT NULL,
    27	                rate_plan VARCHAR(20) NOT NULL,
    28	                nights INTEGER NOT NULL,
    29	                subtotal NUMERIC(12,2) NOT NULL,
    30	                discount NUMERIC(12,2) NOT NULL,
    31	                total NUMERIC(12,2) NOT NULL,
    32	                status VARCHAR(20) NOT NULL,
    33	                amount_paid NUMERIC(12,2) NOT NULL,
    34	                refund NUMERIC(12,2)
    35	            )""",
    36	            """
    37	            CREATE TABLE IF NOT EXISTS messages (
    38	                id BIGSERIAL PRIMARY KEY,
    39	                channel VARCHAR(20) NOT NULL,
    40	                to_address TEXT NOT NULL,
    41	                subject TEXT NOT NULL,
    42	                body TEXT NOT NULL,
    43	                status VARCHAR(20) NOT NULL
    44	            )""");
    45	
    46	    private static final String INSERT_ROOM =
    47	            "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?::numeric) "
    48	                    + "ON CONFLICT (number) DO NOTHING";
    49	
    50	    private static final String[][] ROOMS = {
    51	            {"101", "STANDARD", "2", "249.90"},
    52	            {"102", "STANDARD", "2", "249.90"},
    53	            {"201", "DELUXE", "3", "389.90"},
    54	            {"202", "DELUXE", "3", "389.90"},
    55	            {"301", "SUITE", "4", "579.90"},
    56	    };
    57	
    58	    private Schema() {
    59	    }
    60	
    61	    public static void create(Db db) {
    62	        db.transaction(connection -> {
    63	            try (Statement statement = connection.createStatement()) {
    64	                for (String sql : STATEMENTS) {
    65	                    statement.execute(sql);
    66	                }
    67	            }
    68	            try (PreparedStatement insert = connection.prepareStatement(INSERT_ROOM)) {
    69	                for (String[] room : ROOMS) {
    70	                    insert.setInt(1, Integer.parseInt(room[0]));
    71	                    insert.setString(2, room[1]);
    72	                    insert.setInt(3, Integer.parseInt(room[2]));
    73	                    insert.setString(4, room[3]);
    74	                    insert.executeUpdate();
    75	                }
    76	            }
    77	            return null;
    78	        });
    79	    }
    80	}
