    12	public final class RevenueReport {
    13	    private static final List<String> HEADER =
    14	            List.of("reservation", "room", "check_in", "check_out", "status", "amount");
    15	
    16	    private final Db db;
    17	    private final ReservationRepository reservations;
    18	
    19	    public RevenueReport(Db db, ReservationRepository reservations) {
    20	        this.db = db;
    21	        this.reservations = reservations;
    22	    }
    23	
    24	    public String generate(YearMonth month) {
    25	        return db.transaction(connection -> {
    26	            List<Reservation> kept = reservations
    27	                    .findStartingBetween(connection, month.atDay(1), month.plusMonths(1).atDay(1)).stream()
    28	                    .filter(r -> r.kept().signum() > 0)
    29	                    .toList();
    30	            List<List<String>> rows = kept.stream()
    31	                    .map(r -> List.of(String.valueOf(r.id()), String.valueOf(r.roomNumber()),
    32	                            r.arrival().toString(), r.departure().toString(), r.status().name(),
    33	                            r.kept().toPlainString()))
    34	                    .toList();
    35	            BigDecimal total = kept.stream().map(Reservation::kept).reduce(Money.ZERO, BigDecimal::add);
    36	            return Csv.render(HEADER, rows, Money.round(total).toPlainString());
    37	        });
